            async function handler(event) {
                var request = event.request;
                var __pocketHost = request.headers.host && request.headers.host.value;
                if (__pocketHost && __pocketHost !== 'www.example.com') {
                    var __pocketQs = '';
                    for (var __pocketKey in request.querystring) {
                        var __pocketVal = request.querystring[__pocketKey].value;
                        __pocketQs += (__pocketQs ? '&' : '?') + __pocketKey + (__pocketVal !== '' ? '=' + __pocketVal : '');
                    }
                    return {
                        statusCode: 301,
                        statusDescription: 'Moved Permanently',
                        headers: { location: { value: 'https://www.example.com' + request.uri + __pocketQs } }
                    };
                }
                var __pocketBaAuth = request.headers.authorization;
                var __pocketBaExpected;
                try { __pocketBaExpected = await kvsHandle.get('basic_auth'); }
                catch (e) { __pocketBaExpected = null; }
                if (!__pocketBaExpected || !__pocketBaAuth || __pocketBaAuth.value !== __pocketBaExpected) {
                    return {
                        statusCode: 401,
                        statusDescription: 'Unauthorized',
                        headers: { 'www-authenticate': { value: 'Basic realm="Restricted"' } }
                    };
                }
                var originalUri = request.uri;
                var lastItem = request.uri.split('/').pop();
                if (!lastItem.includes('.')) { request.uri = '/app.html'; }
                var cookie = request.cookies['pocket-spa-token'];
                if (!cookie) { return _redirect(originalUri); }
                // cookie ライブラリによっては値の ':' が %3A に percent-encode される
                // (axum-extra の CookieJar 等)。raw 値には no-op なので常に decode してから分割する。
                var value;
                try { value = decodeURIComponent(cookie.value); }
                catch (e) { return _redirect(originalUri); }
                var parts = value.split(':');
                if (parts.length !== 3) { return _redirect(originalUri); }
                var expiry = parseInt(parts[1], 10);
                if (Math.floor(Date.now() / 1000) > expiry) { return _redirect(originalUri); }
                var secret;
                try { secret = await kvsHandle.get('token_secret'); }
                catch (e) { return _redirect(originalUri); }
                var msg = parts[0] + ':' + parts[1];
                var hmac = crypto.createHmac('sha256', Buffer.from(secret, 'hex'));
                var sig = hmac.update(msg).digest('hex');
                if (sig !== parts[2]) { return _redirect(originalUri); }
                return request;
            }
            function _redirect(uri) {
                var next = encodeURIComponent(uri);
                return { statusCode: 302, statusDescription: 'Found',
                    headers: { location: { value: '/login?next=' + next } } };
            }

